# Beta formula for the public tap alpenlogic/vswitch. The archives are
# attached to the tap's GitHub release; a license is issued separately.
# Generated by packaging/homebrew/build.sh; edit the template, not the tap.
class Vswitch < Formula
  desc "Phone switch for AI agents (licensed beta)"
  homepage "https://github.com/alpenlogic/homebrew-vswitch"
  license :cannot_represent

  on_macos do
    on_arm do
      url "https://github.com/alpenlogic/homebrew-vswitch/releases/download/v0.1.0-beta.4/vswitch-0.1.0-beta.4-darwin-arm64.tar.gz"
      sha256 "c02feab21d609b5bd82da7f4d9c89be7bb0097bb470bd76553dac11bba2ddd09"
    end
    on_intel do
      url "https://github.com/alpenlogic/homebrew-vswitch/releases/download/v0.1.0-beta.4/vswitch-0.1.0-beta.4-darwin-amd64.tar.gz"
      sha256 "f3996d3f49d1fc978b9b56749ae4df420eedcda5443a195addb0e87a6c8106b2"
    end
  end
  on_linux do
    on_arm do
      url "https://github.com/alpenlogic/homebrew-vswitch/releases/download/v0.1.0-beta.4/vswitch-0.1.0-beta.4-linux-arm64.tar.gz"
      sha256 "dc18f2170343142c9d58dc25ab397b96e51bc0ef3afbe81a1fd60d95ede95eba"
    end
    on_intel do
      url "https://github.com/alpenlogic/homebrew-vswitch/releases/download/v0.1.0-beta.4/vswitch-0.1.0-beta.4-linux-amd64.tar.gz"
      sha256 "7f2afd7a0d6e501f6d41937acc15fbc9233def8dedef3f71963aeba5fe6597fb"
    end
  end

  def install
    bin.install Dir["bin/*"]
    libexec.install Dir["tools/*"]
    %w[vswitch-tail vswitch-log vswitch-watch vswitch-edit].each do |tool|
      (bin/tool).write_env_script libexec/tool, VSWITCH_LOGS: var/"vswitch/logs"
    end
    pkgshare.install "README.md", "START-HERE.md", "PROMPTS.md", "VERSION.txt", "vswitch.json", "skill"
  end

  # The configuration and data live outside the keg, so upgrades and
  # reinstalls keep the license, account, numbers and notes. An existing
  # configuration is never replaced.
  post_install_steps do
    mkdir_p "vswitch", base: :var
    set_permissions "vswitch", "0700", base: :var, recursive: false
    mkdir_p "log", base: :var
    mkdir_p "vswitch", base: :etc
    unless_path_exists "vswitch/vswitch.json", base: :etc do
      copy "vswitch.json", "vswitch/vswitch.json", source_base: :pkgshare, target_base: :etc
      inreplace "vswitch/vswitch.json", "@VAR@", "{{var}}", base: :etc
      inreplace "vswitch/vswitch.json", "@ETC@", "{{etc}}", base: :etc
    end
  end

  service do
    run [opt_bin/"vswitch", "-config", etc/"vswitch/vswitch.json", "-verbose=false"]
    # Restarts after a crash and after an announced maintenance restart,
    # which exits with the configuration's restartExitCode (75): on Linux
    # Homebrew makes this systemd Restart=on-failure. A stop stays stopped.
    keep_alive true
    working_dir var/"vswitch"
    log_path var/"log/vswitch.log"
    error_log_path var/"log/vswitch.log"
  end

  def caveats
    <<~EOS
      vSwitch beta. It needs a license: save the license text you were sent as
      #{etc}/vswitch/license.json, then start the switch:
        brew services start vswitch
        curl -s http://127.0.0.1:8087/service

      Start here: numbered steps for you to set up two agents and watch a call:
        #{opt_pkgshare}/README.md
      After the first call, build your team and add optional ring notifications:
        #{opt_pkgshare}/START-HERE.md
    EOS
  end

  test do
    assert_match "usage", shell_output("#{bin}/vswitch-account 2>&1", 1)
    assert_match "state directory", shell_output("#{bin}/vswitch-wait 2>&1", 1)
    # A distributed switch refuses to start without its license.
    (testpath/"c.json").write (pkgshare/"vswitch.json").read.gsub("@VAR@", testpath.to_s).gsub("@ETC@", testpath.to_s)
    assert_match "license", shell_output("#{bin}/vswitch -config #{testpath}/c.json 2>&1", 1)
  end
end
